120→/// Fetch vault keys from backend and decrypt them using the user's private key.
121→///
122→/// Decrypts:
123→/// - Root folder AES-256 key (32 bytes) from ECIES-wrapped hex
124→/// - Root IPNS Ed25519 private key (32 bytes) from ECIES-wrapped hex
125→///
126→/// The IPNS public key is derivable from the private key if ever needed.
127→/// Stores all keys in AppState (memory only).
128→pub(crate) async fn fetch_and_decrypt_vault(state: &AppState) -> Result<(), String> {
129→    log::info!("Fetching and decrypting vault keys");
130→
131→    // GET /vault
132→    let resp = state
133→        .api
134→        .authenticated_get("/vault")
135→        .await
136→        .map_err(|e| format!("Vault fetch failed: {}", e))?;
137→
138→    if !resp.status().is_success() {
139→        let status = resp.status();
140→        let body = resp.text().await.unwrap_or_default();
141→        return Err(format!("Vault fetch failed ({}): {}", status, body));
142→    }
143→
144→    let vault: types::VaultResponse = resp
145→        .json()
146→        .await
147→        .map_err(|e| format!("Failed to parse vault response: {}", e))?;
148→
149→    // Get private key for decryption
150→    let private_key = state
151→        .private_key
152→        .read()
153→        .await
154→        .as_ref()
155→        .ok_or("Private key not available for vault decryption")?
156→        .clone();
157→
158→    // Decrypt root folder key
159→    let encrypted_root_folder_key = hex::decode(&vault.encrypted_root_folder_key)
160→        .map_err(|_| "Invalid encryptedRootFolderKey hex")?;
161→    let root_folder_key = crypto::ecies::unwrap_key(&encrypted_root_folder_key, &private_key)
162→        .map_err(|e| format!("Failed to decrypt root folder key: {}", e))?;
163→    *state.root_folder_key.write().await = Some(root_folder_key);
164→
165→    // Decrypt root IPNS private key
166→    let encrypted_root_ipns_private_key = hex::decode(&vault.encrypted_root_ipns_private_key)
167→        .map_err(|_| "Invalid encryptedRootIpnsPrivateKey hex")?;
168→    let root_ipns_private_key =
169→        crypto::ecies::unwrap_key(&encrypted_root_ipns_private_key, &private_key)
170→            .map_err(|e| format!("Failed to decrypt root IPNS private key: {}", e))?;
171→
172→    // Verify stored IPNS key matches HKDF derivation (consistency check)
173→    let private_key_arr: [u8; 32] = private_key
174→        .as_slice()
175→        .try_into()
176→        .map_err(|_| "Invalid private key length for HKDF check")?;
177→    if let Ok((expected_ipns_key, _, _)) = crypto::hkdf::derive_vault_ipns_keypair(&private_key_arr) {
178→        if root_ipns_private_key != *expected_ipns_key {
179→            log::warn!("Vault IPNS key mismatch: stored key differs from HKDF derivation");
180→            // Don't block - proceed with stored key for backward compatibility
181→        }
182→    }
183→
184→    *state.root_ipns_private_key.write().await = Some(root_ipns_private_key);
185→
186→    // Store IPNS name and TEE keys
187→    *state.root_ipns_name.write().await = Some(vault.root_ipns_name);
188→    *state.tee_keys.write().await = vault.tee_keys;
189→
190→    log::info!("Vault keys decrypted and stored in memory");
191→    Ok(())
192→}
